SELECT 
FROM andon_reason
WHERE is_deleted = 0

    AND (reason_name LIKE CONCAT('%', #{keyword}, '%')
         OR reason_code LIKE CONCAT('%', #{keyword}, '%'))


    AND andon_type_id = #{andonTypeId}


    AND status = #{status}

ORDER BY sort_order ASC, id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM andon_reason WHERE is_deleted = 0
AND (reason_name LIKE CONCAT('%', #{keyword}, '%') OR reason_code LIKE CONCAT('%', #{keyword}, '%'))
AND andon_type_id = #{andonTypeId}
AND status = #{status}
